async Task DemoAsync()
{
    Console.WriteLine("A");      // сразу, в вызывающем потоке
    await Task.Delay(100);       // настоящая пауза: метод вернул Task
    Console.WriteLine("C");      // продолжение — позже
}
var t = DemoAsync();             // напечатано A
Console.WriteLine("B");
await t;                         // C

